import type { ProtocolAdapter } from "../types";
import { AdapterResponseError, ConfigReader, hostOf, requireRemoteId, resolveExpiry, validUri, ValuesBuilder } from "./base";
import { remarkGuard } from "./guards";

/**
 * Shadowsocks. Expected `config`: { host, port, method, password, plugin?, plugin_opts?, uri? }.
 * The password is generated by the node.
 */
export const shadowsocksAdapter: ProtocolAdapter = {
  key: "shadowsocks",
  label: "Shadowsocks",
  description: "Shadowsocks account (SIP002 share link + QR code).",
  inputGuards: { username: remarkGuard },
  requiredInputs: ["username"],
  supportsRenew: true,
  outputFields: [
    { key: "host", label: "Server", kind: "text", sensitive: false, copyable: true },
    { key: "port", label: "Port", kind: "text", sensitive: false, copyable: true },
    { key: "method", label: "Encryption method", kind: "text", sensitive: false, copyable: true },
    { key: "password", label: "Password", kind: "secret", sensitive: true, copyable: true },
    { key: "plugin", label: "Plugin", kind: "text", sensitive: false, copyable: true },
    { key: "plugin_opts", label: "Plugin options", kind: "text", sensitive: false, copyable: true },
  ],
  defaultFields: [
    {
      key: "username",
      label: "Username",
      type: "text",
      required: true,
      placeholder: "e.g. traveller",
      helpText: "Used as the account remark.",
      options: [],
      validation: { minLength: 3, maxLength: 32 },
    },
    { key: "duration", label: "Duration", type: "duration", required: true, options: [], validation: {} },
  ],

  buildSpec(input, ctx) {
    return {
      protocol: ctx.serverProtocol.nodeIdentifier ?? ctx.protocol.slug,
      username: input.username,
      durationDays: input.durationDays,
      options: input.options,
    };
  },

  parseAccount(account, ctx, input) {
    const cfg = new ConfigReader(account.config);
    const host = hostOf(cfg, ctx);
    const port = cfg.int("port");
    const method = cfg.str("method", 64);
    const password = cfg.str("password", 256);
    if (!port || !method || !password) throw new AdapterResponseError("Server did not return port, method and password.");
    const plugin = cfg.str("plugin", 64);
    const pluginOpts = cfg.str("plugin_opts", 512);
    const remark = account.username ?? input.username ?? "shadowsocks";

    let uri = validUri(cfg.str("uri", 4096), "shadowsocks");
    if (!uri) {
      const userinfo = Buffer.from(`${method}:${password}`).toString("base64url");
      const pluginParam = plugin ? `/?plugin=${encodeURIComponent(pluginOpts ? `${plugin};${pluginOpts}` : plugin)}` : "";
      uri = `ss://${userinfo}@${host}:${port}${pluginParam}#${encodeURIComponent(remark)}`;
    }

    const v = new ValuesBuilder()
      .set("host", host)
      .set("port", port)
      .set("method", method)
      .set("password", password, true)
      .set("plugin", plugin)
      .set("plugin_opts", pluginOpts);

    return {
      remoteAccountId: requireRemoteId(account),
      username: account.username ?? input.username,
      expiresAt: resolveExpiry(account, input),
      values: v.values,
      artifacts: [{ key: "link", label: "Shadowsocks link", kind: "uri", content: uri, qr: true, sensitive: true }],
    };
  },
};
